(()=>{'use strict';if(typeof globalThis.crypto==='undefined'||typeof globalThis.crypto.randomUUID==='function')return;const uuid=()=>{const bytes=new Uint8Array(16);globalThis.crypto.getRandomValues(bytes);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const s=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return s.slice(0,8)+'-'+s.slice(8,12)+'-'+s.slice(12,16)+'-'+s.slice(16,20)+'-'+s.slice(20);};if(typeof globalThis.crypto.getRandomValues==='function')Object.defineProperty(globalThis.crypto,'randomUUID',{value:uuid,configurable:true});})();
